SELECT FROM proveedor pr LEFT JOIN persona p ON p.id = pr.persona_id AND p.deleted = FALSE
pr.deleted = FALSE AND (p.nombre ILIKE '%' || #{nombre} '%' OR p.primer_apellido ILIKE '%' || #{nombre} '%' OR pr.empresa ILIKE '%' || #{nombre} '%')
ORDER BY pr.created_at DESC LIMIT #{limit} OFFSET #{offset}
